const express = require('express');
const app = express();
const PORT = 3000;

// Basic Route
app.get('/status', (req, res) => {
  res.json({ status: 'Server is running', port: PORT });
});

// Boot the server
app.listen(PORT, () => {
  console.log(`Server listening at http://localhost:${PORT}`);
});
